	[TestMethod]
	public void static_position_static_root()
	{
		var root = CreateNode();
		root.Style.PositionType = PositionType.Static;
		root.Style.SetPadding( Edge.Left, StyleLength.Points( 6 ) );
		root.Style.SetPadding( Edge.Top, StyleLength.Points( 1 ) );
		root.Style.SetPadding( Edge.Right, StyleLength.Points( 11 ) );
		root.Style.SetPadding( Edge.Bottom, StyleLength.Points( 4 ) );
		root.Style.Width = StyleLength.Points( 100 );
		root.Style.Height = StyleLength.Points( 200 );

		var root_child0 = CreateNode();
		root_child0.Style.PositionType = PositionType.Absolute;
		root_child0.Style.SetMargin( Edge.Left, StyleLength.Points( 12 ) );
		root_child0.Style.SetMargin( Edge.Top, StyleLength.Points( 11 ) );
		root_child0.Style.SetMargin( Edge.Right, StyleLength.Points( 15 ) );
		root_child0.Style.SetMargin( Edge.Bottom, StyleLength.Points( 1 ) );
		root_child0.Style.SetPadding( Edge.Left, StyleLength.Points( 3 ) );
		root_child0.Style.SetPadding( Edge.Top, StyleLength.Points( 7 ) );
		root_child0.Style.SetPadding( Edge.Right, StyleLength.Points( 5 ) );
		root_child0.Style.SetPadding( Edge.Bottom, StyleLength.Points( 4 ) );
		root_child0.Style.SetBorder( Edge.Left, StyleLength.Points( 4 ) );
		root_child0.Style.SetBorder( Edge.Top, StyleLength.Points( 3 ) );
		root_child0.Style.SetBorder( Edge.Right, StyleLength.Points( 2 ) );
		root_child0.Style.SetBorder( Edge.Bottom, StyleLength.Points( 1 ) );
		root_child0.Style.Width = StyleLength.Percent( 50 );
		root_child0.Style.Height = StyleLength.Percent( 50 );
		root.InsertChild( root_child0, 0 );
		root.CalculateLayout( float.NaN, float.NaN, Direction.LTR );

		AssertEq( 0, FixtureGeometry.GetRect( root, true ).Left, "root.Left" );
		AssertEq( 0, FixtureGeometry.GetRect( root, true ).Top, "root.Top" );
		AssertEq( 100, FixtureGeometry.GetRect( root, true ).Width, "root.Width" );
		AssertEq( 200, FixtureGeometry.GetRect( root, true ).Height, "root.Height" );

		AssertEq( 18, FixtureGeometry.GetRect( root_child0, true ).Left, "root_child0.Left" );
		AssertEq( 12, FixtureGeometry.GetRect( root_child0, true ).Top, "root_child0.Top" );
		AssertEq( 50, FixtureGeometry.GetRect( root_child0, true ).Width, "root_child0.Width" );
		AssertEq( 100, FixtureGeometry.GetRect( root_child0, true ).Height, "root_child0.Height" );

		root.CalculateLayout( float.NaN, float.NaN, Direction.RTL );

		AssertEq( 0, FixtureGeometry.GetRect( root, true ).Left, "root.Left" );
		AssertEq( 0, FixtureGeometry.GetRect( root, true ).Top, "root.Top" );
		AssertEq( 100, FixtureGeometry.GetRect( root, true ).Width, "root.Width" );
		AssertEq( 200, FixtureGeometry.GetRect( root, true ).Height, "root.Height" );

		AssertEq( 24, FixtureGeometry.GetRect( root_child0, true ).Left, "root_child0.Left" );
		AssertEq( 12, FixtureGeometry.GetRect( root_child0, true ).Top, "root_child0.Top" );
		AssertEq( 50, FixtureGeometry.GetRect( root_child0, true ).Width, "root_child0.Width" );
		AssertEq( 100, FixtureGeometry.GetRect( root_child0, true ).Height, "root_child0.Height" );
	}

